import { TeeError } from '../common/tee-error';

/** Account IDs are generated by core: a 3–32-char slug, any collision suffix fitting inside 32. */
const ACCOUNT_SLUG_RE = /^[a-z0-9][a-z0-9-]{2,31}$/;

export function assertValidAccountSlug(slug: unknown): string {
  if (typeof slug !== 'string' || !ACCOUNT_SLUG_RE.test(slug)) {
    throw new TeeError('TEE_INVALID_SLUG', 'account slug must be a lowercase slug', {
      expected: 'lowercase letters, digits and hyphens; must start alphanumeric; 3–32 chars',
    });
  }
  return slug;
}
